function out = run_b1_waterfall_three_dataset_comparison(options)
%RUN_B1_WATERFALL_THREE_DATASET_COMPARISON Combine three B1 waterfall plots.
%
% The input panels are the per-session waterfall images generated by
% run_b1_double_peak_binning_analysis. This script keeps the original panels
% unchanged and only assembles a side-by-side comparison figure.

arguments
    options.dateTag {mustBeTextScalar} = "260509"
    options.mode {mustBeTextScalar} = "signed_q"
end

script_dir = fileparts(mfilename('fullpath'));
project_root = bisb_find_project_root(script_dir);
results_root = fullfile(project_root, 'paper_results');

date_tag = char(string(options.dateTag));
mode = char(string(options.mode));
if strcmp(mode, 'absq_combined')
    error('run_b1_waterfall_three_dataset_comparison:DeprecatedAbsQCombined', ...
        ['absq_combined waterfall comparisons are obsolete because they ', ...
        'average +q and -q. Use signed_q instead.']);
end

sessions = local_sessions(date_tag);
input_name = sprintf('b1_double_peak_waterfall_%s.png', mode);
images = cell(1, numel(sessions));
source_paths = strings(1, numel(sessions));

for i = 1:numel(sessions)
    source_paths(i) = string(fullfile(results_root, sessions(i).folder, input_name));
    if ~isfile(source_paths(i))
        error('run_b1_waterfall_three_dataset_comparison:MissingInput', ...
            'Missing waterfall image: %s', source_paths(i));
    end
    images{i} = local_read_rgb(source_paths(i));
end

gap_px = 55;
canvas = local_concat_horizontal(images, gap_px);

out_dir = fullfile(results_root, sprintf('b1_double_peak_waterfall_three_dataset_comparison_%s', date_tag));
if ~isfolder(out_dir)
    mkdir(out_dir);
end

base_name = sprintf('b1_double_peak_waterfall_%s_three_dataset_comparison', mode);
out = struct();
out.output_dir = out_dir;
out.png = fullfile(out_dir, [base_name '.png']);
out.pdf = fullfile(out_dir, [local_pdf_base_name(mode) '.pdf']);
out.source_paths = source_paths;

imwrite(canvas, out.png);

fig = figure('Visible', 'off', 'Color', 'w', ...
    'Position', [50 50 min(size(canvas, 2), 5600) min(size(canvas, 1), 2800)]);
ax = axes(fig);
image(ax, canvas);
axis(ax, 'image');
axis(ax, 'off');
title(ax, sprintf('B1 double-peak waterfall comparison | %s | %s', ...
    local_mode_label(mode), date_tag), 'Interpreter', 'none');
exportgraphics(fig, out.pdf, 'ContentType', 'vector');
if ~isfile(out.pdf)
    print(fig, out.pdf, '-dpdf', '-bestfit');
end
close(fig);

fprintf('Three-dataset waterfall comparison written:\n  %s\n  %s\n', ...
    out.png, out.pdf);
end


function sessions = local_sessions(date_tag)
sessions = struct( ...
    'folder', { ...
        sprintf('590_gui_history_area_260506_b1_double_peak_binning_%s', date_tag), ...
        sprintf('n0_PL2_10w_gui_history_area_260506_b1_double_peak_binning_%s', date_tag), ...
        sprintf('no_PL2_20w_2film_gui_history_area_260506_highq_refined_b1_double_peak_binning_%s', date_tag)});
end


function img = local_read_rgb(path)
img = imread(path);
if ndims(img) == 2
    img = repmat(img, 1, 1, 3);
elseif size(img, 3) > 3
    img = img(:, :, 1:3);
end
end


function canvas = local_concat_horizontal(images, gap_px)
n = numel(images);
heights = cellfun(@(x) size(x, 1), images);
widths = cellfun(@(x) size(x, 2), images);
max_h = max(heights);
total_w = sum(widths) + gap_px * (n - 1);
canvas = uint8(255 * ones(max_h, total_w, 3));

x0 = 1;
for i = 1:n
    img = images{i};
    h = size(img, 1);
    w = size(img, 2);
    y0 = floor((max_h - h) / 2) + 1;
    canvas(y0:(y0+h-1), x0:(x0+w-1), :) = img;
    x0 = x0 + w + gap_px;
end
end


function label = local_mode_label(mode)
switch char(mode)
    case 'signed_q'
        label = 'signed q';
    case 'signed_q_start50meV'
        label = 'signed q | start 50 meV';
    case 'signed_q_area250_3800norm_start50meV'
        label = 'signed q | area 250-3800 norm | start 50 meV';
    case 'signed_q_area50_3800norm_start50meV'
        label = 'signed q | area 50-3800 norm | start 50 meV';
    case 'signed_q_area50_3800norm_start250meV_end1600meV_residual_gain2'
        label = 'signed q | area 50-3800 norm | 250-1600 meV | residual | gain 2';
    case 'absq_combined'
        label = 'obsolete |q| combined';
    case 'combined_q'
        label = 'combined-q binning';
    otherwise
        label = char(mode);
end
end


function name = local_pdf_base_name(mode)
switch char(mode)
    case 'signed_q_area50_3800norm_start250meV_end1600meV_residual_gain2'
        name = 'b1_double_peak_waterfall_signed_q_residual_gain2_three_dataset_comparison';
    otherwise
        name = sprintf('b1_double_peak_waterfall_%s_three_dataset_comparison', char(mode));
end
end
